import { test, expect } from '@playwright/test';

test.describe('Email Address Change with Confirmation Step', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully change email address with confirmation step', async ({ page }) => {
    // Setup: Fill in current email
    const emailInput = page.getByLabel('Current Email Address');
    await emailInput.fill('user@example.com');

    // Setup: Fill in new email
    const newEmailInput = page.getByLabel('New Email Address');
    await newEmailInput.fill('newuser@example.com');

    // Setup: Click change button
    const changeButton = page.getByRole('button', { name: /change email/i });
    await changeButton.click();

    // Verify confirmation modal appears
    const confirmationModal = page.locator('[data-testid="confirmation-modal"]');
    await expect(confirmationModal).toBeVisible();

    // Verify confirmation button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Verify cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify email input fields are populated
    await expect(emailInput).toHaveValue('newuser@example.com');
    await expect(newEmailInput).toHaveValue('newuser@example.com');

    // Verify success message is displayed
    const successMessage = page.getByText(/email address changed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to profile page
    await expect(page).toHaveURL(/profile/);
  });

  test('should display error when confirmation fails', async ({ page }) => {
    // Setup: Fill in current email
    const emailInput = page.getByLabel('Current Email Address');
    await emailInput.fill('user@example.com');

    // Setup: Fill in new email
    const newEmailInput = page.getByLabel('New Email Address');
    await newEmailInput.fill('invalid-email');

    // Setup: Click change button
    const changeButton = page.getByRole('button', { name: /change email/i });
    await changeButton.click();

    // Verify confirmation modal appears
    const confirmationModal = page.locator('[data-testid="confirmation-modal"]');
    await expect(confirmationModal).toBeVisible();

    // Verify confirmation button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid email address/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is not redirected
    await expect(page).toHaveURL(/profile/);
  });
});
